**Goal:**

*   Create a reusable Tooltip component in Next.js.
*   Use React Context to manage the active Tooltip.
*   When a new Tooltip is opened, close the previously active one.
*   Provide a simple API to open and close Tooltips programmatically.

**Implementation:**

1.  **Tooltip Context:**

    ```javascript
    // TooltipContext.js
    import React, { createContext, useState, useContext, useCallback } from 'react';

    const TooltipContext = createContext({
      activeTooltipId: null,
      setActiveTooltipId: (id) => {},
    });

    export const TooltipProvider = ({ children }) => {
      const [activeTooltipId, setActiveTooltipId] = useState(null);

      const setActiveTooltip = useCallback((id) => {
        setActiveTooltipId((prevId) => {
          if (id === prevId) {
            return id; // Prevent unnecessary re-renders if the same tooltip is being opened again
          }
          if (prevId) {
            // Close the previous tooltip
            return null;
          }
          return id;
        });
      }, []);

      const value = {
        activeTooltipId,
        setActiveTooltipId: setActiveTooltip,
      };

      return (
        <TooltipContext.Provider value={value}>
          {children}
        </TooltipContext.Provider>
      );
    };

    export const useTooltip = () => useContext(TooltipContext);
    ```

