    `;

    const TooltipContent = styled.div`
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      margin-top: 8px;
    `;

    const Tooltip = ({ children, content, id }) => {
      const [isOpen, setIsOpen] = useState(false);
      const { activeTooltipId, setActiveTooltip } = useTooltip();

      useEffect(() => {
        if (activeTooltipId === id) {
          setIsOpen(true);
        } else {
          setIsOpen(false);
        }
      }, [activeTooltipId, id]);

      const handleMouseEnter = () => {
        setActiveTooltip(id);
      };

      const handleMouseLeave = () => {
        setActiveTooltip(null);
      };

      return (
        <TooltipTrigger
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
        >
          {children}
          <TooltipContent>
            <TooltipContainer className={isOpen ? 'active' : ''}>
              {content}
            </TooltipContainer>
          </TooltipContent>
        </TooltipTrigger>
      );
    };

    export default Tooltip;
