*   **`table class="table table-bordered"`:**  This uses Bootstrap's basic table styling.  You can add other Bootstrap table classes as needed.
*   **`<thead>` and `<tbody>`:** Standard table structure.
*   **`<th>` (Table Headers):**  Crucially, each header cell has a `data-sort` attribute.  This attribute tells our JavaScript what type of sorting to apply to that column.  Possible values:
    *   `string`: For text-based sorting (alphanumeric).
    *   `number`: For numeric sorting.
    *   `date`: For date sorting (assuming dates are in a consistent format like YYYY-MM-DD).

**2. JavaScript (Sorting Logic)**

```javascript
const table = document.querySelector('.table');
let sortColumn = null;
let sortOrder = 1; // 1 = ascending, -1 = descending

table.querySelectorAll('th').forEach(header => {
  header.addEventListener('click', () => {
    const sortType = header.dataset.sort;
    const columnIndex = header.cellIndex;

    if (sortColumn === columnIndex) {
      sortOrder *= -1; // Toggle sort order
    } else {
      sortColumn = columnIndex;
      sortOrder = 1;
    }

    sortTable(columnIndex, sortOrder, sortType);
  });
});

function sortTable(columnIndex, sortOrder, sortType) {
  const rows = Array.from(table.querySelectorAll('tbody tr'));

  rows.sort((a, b) => {
    const cellA = a.cells[columnIndex].textContent.trim();
    const cellB = b.cells[columnIndex].textContent.trim();

    let comparison = 0;

    switch (sortType) {
      case 'string':
        comparison = cellA.localeCompare(cellB, undefined, { numeric: true, sensitivity: 'base' });
        break;
      case 'number':
        comparison = parseFloat(cellA) - parseFloat(cellB);
        break;
      case 'date':
        comparison = new Date(cellA) - new Date(cellB);
        break;
      default:
        comparison = cellA.localeCompare(cellB); // Default to string comparison
    }

    return sortOrder * comparison;
  });

  // Clear the table body and re-append sorted rows
  table.querySelector('tbody').innerHTML = '';
  rows.forEach(row => table.querySelector('tbody').appendChild(row));
}
```

