        this.jdbcTemplate = jdbcTemplate;
        this.sqlQuery = readSqlQueryFromFile(sqlQueryFile);
        this.outputFile = outputFile;
    }

    private String readSqlQueryFromFile(String filePath) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            return reader.readLine();
        }
    }

    @Scheduled(cron = "0 0 12 * * ?") // Runs every day at 12:00 PM
    public void executeSqlQueryAndWriteToFile() {
        try {
            List<String> results = jdbcTemplate.queryForList(sqlQuery, String.class);

            try (FileWriter writer = new FileWriter(outputFile, true)) { // Append to file
                for (String result : results) {
                    writer.write(result + "\n");
                }
            }

            System.out.println("SQL query executed and results written to file: " + outputFile);

        } catch (Exception e) {
            System.err.println("Error executing SQL query or writing to file: " + e.getMessage());
            e.printStackTrace();
        }
    }
}
